// runOnceForAllItems
const allItems = $input.all();
const results  = [];

for (const item of allItems) {
  const j = item.json;

  // 1 — extract raw text from all known OpenAI v2.1 shapes
  let rawText = '';
  const t = j?.output?.[0]?.content?.[0]?.text;
  if (typeof t === 'string' && t.trim()) rawText = t.trim();
  else if (typeof j?.content === 'string' && j.content.trim()) rawText = j.content.trim();

  if (!rawText) {
    throw new Error('Empty OpenAI response. Input keys: ' + Object.keys(j || {}).join(', '));
  }

  // 2 — extract JSON by first { and last }
  const s = rawText.indexOf('{');
  const e = rawText.lastIndexOf('}');
  if (s < 0 || e <= s) {
    throw new Error('No JSON object found. Text snippet: ' + rawText.slice(0, 200));
  }

  let parsed;
  try {
    parsed = JSON.parse(rawText.slice(s, e + 1));
  } catch(err) {
    throw new Error('JSON.parse failed: ' + err.message + ' | snippet: ' + rawText.slice(s, s + 200));
  }

  // 3 — whitelist every candidate field (no LLM-invented keys survive)
  const candidate = {
    cv:            !!parsed.cv,
    full_name:     String(parsed.full_name     || ''),
    sex:           String(parsed.sex           || ''),
    birth_date:    parsed.birth_date           || null,
    contact_phone: parsed.contact_phone        || null,
    email:         String(parsed.email         || ''),
    country:       parsed.country              || null,
    city:          parsed.city                 || null,
    citizenship:   parsed.citizenship          || null,
    position:      String(parsed.position      || ''),
    employment:    parsed.employment           || null,
    experience:    parseInt(parsed.experience) || 0,
    skills:        Array.isArray(parsed.skills) ? parsed.skills.map(s => String(s)) : [],
    salary:        parsed.salary ? parseInt(parsed.salary) : null
  };

  // 4 — get Gmail sender (safe: non-fatal if not in context)
  let emailFrom = '', emailSubject = '', messageId = '';
  try {
    const g = $('Gmail Trigger').first().json;
    const f = g && g.from;
    emailFrom    = (f && f.value && f.value[0] && f.value[0].address)
                    || (typeof f === 'string' ? f : '') || '';
    emailSubject = String((g && g.subject) || '');
    messageId    = String((g && g.id)      || '');
  } catch(_) {}

  // 5 — deep-clone ensures pure POJO (no class instances, no circular refs)
  results.push({ json: JSON.parse(JSON.stringify({
    cv:           candidate.cv,
    candidate:    candidate,
    emailFrom:    emailFrom,
    emailSubject: emailSubject,
    messageId:    messageId
  })) });
}

return results;

// Collect vacancies from Google Sheets and build OpenAI matching input
const parsed = $('Parse Candidate JSON').first().json;
const candidate = parsed.candidate;
const emailFrom = parsed.emailFrom;
const emailSubject = parsed.emailSubject;
const messageId = parsed.messageId;

const vacancies = items
  .map((item, index) => ({
    row_number: index + 2,
    title: item.json['Должность'] || item.json['title'] || '',
    description: [
      item.json['Описание'] || item.json['description'] || '',
      item.json['Требования'] || item.json['requirements'] || '',
      item.json['Зарплата'] ? 'Зарплата: ' + item.json['Зарплата'] : ''
    ].filter(Boolean).join('. ')
  }))
  .filter(v => v.title);

if (vacancies.length === 0) {
  throw new Error('No vacancies found in Google Sheets. Please fill the Вакансии sheet.');
}

const userContent = JSON.stringify({ candidate, vacancies });
return [{ json: { userContent, candidate, vacancies, emailFrom, emailSubject, messageId } }];

// runOnceForAllItems
const allItems = $input.all();
const results  = [];

for (const item of allItems) {
  const j = item.json;

  // 1 — extract raw text
  let rawText = '';
  const t = j?.output?.[0]?.content?.[0]?.text;
  if (typeof t === 'string' && t.trim()) rawText = t.trim();
  else if (typeof j?.content === 'string' && j.content.trim()) rawText = j.content.trim();

  if (!rawText) {
    throw new Error('Empty OpenAI response. Input keys: ' + Object.keys(j || {}).join(', '));
  }

  // 2 — extract JSON by braces
  const s = rawText.indexOf('{');
  const e = rawText.lastIndexOf('}');
  if (s < 0 || e <= s) {
    throw new Error('No JSON object found. Text snippet: ' + rawText.slice(0, 200));
  }

  let parsed;
  try {
    parsed = JSON.parse(rawText.slice(s, e + 1));
  } catch(err) {
    throw new Error('JSON.parse failed: ' + err.message + ' | snippet: ' + rawText.slice(s, s + 200));
  }

  // 3 — whitelist all fields
  const sum = parsed.candidate_summary || {};
  const candidateSummary = {
    full_name:                       String(sum.full_name || ''),
    position_raw:                    String(sum.position_raw || ''),
    position_family:                 String(sum.position_family || ''),
    normalized_skills:               Array.isArray(sum.normalized_skills) ? sum.normalized_skills.map(String) : [],
    experience_years:                parseInt(sum.experience_years) || 0,
    seniority:                       String(sum.seniority || ''),
    employment:                      String(sum.employment || ''),
    city:                            String(sum.city || ''),
    country:                         String(sum.country || ''),
    salary_expectation_rub_per_month: parseInt(sum.salary_expectation_rub_per_month) || 0,
    contacts:                        String(sum.contacts || '')
  };

  const cleanMatch = m => ({
    row_number: parseInt(m.row_number) || 0,
    title:      String(m.title  || ''),
    family:     String(m.family || ''),
    score:      parseInt(m.score) || 0,
    reasons:    Array.isArray(m.reasons) ? m.reasons.map(String) : [],
    risks:      Array.isArray(m.risks)   ? m.risks.map(String)   : []
  });

  const allMatches       = (parsed.matches    || []).map(cleanMatch);
  const qualifiedMatches = allMatches.filter(m => m.score >= 60);

  const prev = $('Prepare Matching').first().json;

  results.push({ json: JSON.parse(JSON.stringify({
    hasMatch:         qualifiedMatches.length >= 1,
    matches:          qualifiedMatches,
    nearMisses:       (parsed.near_misses || []).map(cleanMatch),
    candidateSummary: candidateSummary,
    emailFrom:        String((prev && prev.emailFrom) || ''),
    messageId:        String((prev && prev.messageId) || ''),
    candidate:        (prev && prev.candidate) ? JSON.parse(JSON.stringify(prev.candidate)) : {}
  })) });
}

return results;

// runOnceForAllItems — expand PDF attachments into separate items
const results = [];

for (const item of $input.all()) {
  const binary = item.binary ?? {};

  const pdfs = Object.entries(binary)
    .filter(([key]) => key.startsWith('attachment'))
    .filter(([_, att]) =>
      att.mimeType === 'application/pdf' ||
      (att.fileName ?? '').toLowerCase().endsWith('.pdf')
    );

  for (const [key, att] of pdfs) {
    results.push({
      json: {
        ...item.json,
        hasPDF: true,          // ← THIS was missing: If node checks this
        attachmentKey: key,
        fileName: att.fileName ?? key
      },
      binary: { pdf: att }
    });
  }
}

// No PDF found — return item with hasPDF: false
if (results.length === 0) {
  return [{ json: { ...$input.first().json, hasPDF: false } }];
}

return results;

